import {ribbonMatchCases,ribbonMatchPages} from './ribbon-matches-content.mjs';
import {matchView,startMatch,resumeMatch,setMatchPage,startMatchFlag,moveMatchFlag,chooseMatchProposal,chooseMatchNumerator,addMatchSupport,checkMatch,matchCheckMatches,matchReferenceLabel,matchWorkingLabel,matchWorkingDescription,matchWorkingPictureText} from './ribbon-matches-core.mjs';
import {ribbonMatchesDiagram} from './ribbon-matches-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const outcome=x=>x===null?'unobserved':x?'fits':'does not fit';
const proposal=x=>x==='flag'?'Use the flag as our proposed match':x==='unsure'?'Not sure about the match':'No matching response yet';
const numerator=x=>x===null?'blank':x==='unsure'?'not sure':String(x);
const recordHeading=(r,c,i)=>i<r.checks.length-1?'Earlier recorded check':matchCheckMatches(r,c)?'Latest check of these choices':'Latest check · choices or support changed since';
function figure(r){const s=r.source,description=matchWorkingDescription(s,r.index);return `<figure class="ribbon-match-figure"><div class="ribbon-match-row-label"><strong>Fixed reference: ${esc(matchReferenceLabel(s))}</strong><span>Top: ${s.referenceDenominator} equal parts · given label</span><span>Bottom: our working ribbon · ${s.workingDenominator} equal parts · same whole</span></div>${s.drawingVersion===1?`<div class="ribbon-match-paired-art">${ribbonMatchesDiagram(s,r.index,{workingDescription:description})}</div>`:`<div class="ribbon-match-picture-fallback"><p>This saved drawing version is unavailable. The original reference description is: ${esc(s.referencePictureText)}</p><p class="ribbon-match-fallback-working">${esc(matchWorkingPictureText(s,r.index))}</p></div>`}<figcaption><span>Outlined rows are equal wholes. Thick lower lines mark selected prefixes; poles mark their endpoints.</span><strong>${r.index===null?'No working flag yet.':r.proposal==='flag'?'Our working flag is proposed as the match.':r.proposal==='unsure'?'Working flag retained; matching response is not sure.':'Working flag retained; no matching response chosen.'}</strong></figcaption><details><summary>Ribbon picture descriptions</summary><p>Fixed reference: ${esc(s.referencePictureText)}</p><p>Working ribbon: ${esc(description)}</p></details></figure>`;}
function makePage(r){return `<h2 id="ribbon-match-prompt" tabindex="-1">${esc(r.source.request)}</h2><div class="ribbon-match-turn"><div>${figure(r)}</div><section class="ribbon-match-actions"><p class="ribbon-match-task">Keep the reference fixed. Our working ribbon has <strong>${r.source.workingDenominator} equal parts</strong>.</p>${button('data-ribbon-match-start-flag','Start the flag at zero')}<div class="ribbon-match-step-controls" role="group" aria-label="Move the working flag by one part">${button(`data-ribbon-match-move="-1"${r.index===null||r.index===0?' disabled':''}`,'Back one part')}${button(`data-ribbon-match-move="1"${r.index===null||r.index===r.source.workingDenominator?' disabled':''}`,'Forward one part')}</div><div class="ribbon-match-proposal-controls">${button(`data-ribbon-match-proposal="flag" aria-pressed="${r.proposal==='flag'}"${r.index===null?' disabled':''}`,'Use this flag',r.proposal==='flag')}${button(`data-ribbon-match-proposal="unsure" aria-pressed="${r.proposal==='unsure'}"`,'Not sure about the match',r.proposal==='unsure')}</div>${button('data-ribbon-match-page="name"','Next: name our working flag',true)}${hearButton(r.source.request+' '+r.source.referencePictureText,'Hear the request and reference description')}</section></div><details><summary>Our market-label job</summary><p>${esc(r.source.story)}</p></details>`;}
function namePage(r){return `<h2 id="ribbon-match-prompt" tabindex="-1">${esc(r.source.namingPrompt)}</h2><div class="ribbon-match-turn"><div>${figure(r)}</div><section class="ribbon-match-actions"><p class="ribbon-match-task">Our working ribbon has <strong>${r.source.workingDenominator} equal parts</strong>, so that is the denominator. Choose the numerator for our actual working flag.</p>${r.index===null?'<p class="ribbon-match-no-flag">The flag still needs a position. You can retain a number choice, but it cannot yet be checked against a flag.</p>':''}<div class="ribbon-match-numerators" role="group" aria-label="Choose the working numerator">${Array.from({length:r.source.workingDenominator+1},(_,i)=>button(`data-ribbon-match-numerator="${i}" aria-pressed="${r.numerator===i}"`,String(i),r.numerator===i)).join('')}</div>${button(`data-ribbon-match-numerator="unsure" aria-pressed="${r.numerator==='unsure'}"`,'Not sure yet',r.numerator==='unsure')}${button('data-ribbon-match-clear-numerator','Leave naming blank')}${button('data-ribbon-match-check','Check / keep this trail',true)}<p class="tiny">Latest 8 checks stay here; a ninth removes the oldest. Checking is open with blank or uncertain work.</p>${button('data-ribbon-match-page="make"','Change our working flag')}</section></div>`;}
function frozenSource(s){return `<details class="ribbon-match-frozen-source"><summary>Original request and source kept with this check</summary><h4>${esc(s.title)}</h4><p>${esc(s.story)}</p><p>${esc(s.request)}</p><p>Fixed reference: ${s.referenceNumerator}/${s.referenceDenominator}; working partition: ${s.workingDenominator} equal parts. Same declared whole: length ${s.wholeLength} model ticks, width ${s.wholeWidth} model unit.</p><p>Original reference description: ${esc(s.referencePictureText)}</p><p>${esc(s.namingPrompt)}</p><p>${esc(s.help)}</p></details>`;}
function checkRecord(r,c,i){return `<section class="ribbon-match-record" tabindex="-1"><h3>${recordHeading(r,c,i)}</h3><p class="ribbon-match-feedback">${esc(c.feedback)}</p><p><strong>Recorded amount outcome:</strong> ${outcome(c.amountMatch)}.<br><strong>Recorded naming outcome:</strong> ${outcome(c.namingMatch)}.<br><strong>Recorded both fit:</strong> ${c.fulfilled?'yes':'no'}.</p><p><strong>Recorded reference label:</strong> ${esc(c.referenceLabel)}.<br><strong>Recorded working label:</strong> ${esc(c.workingLabel===null?'No label recorded':c.workingLabel)}.</p><details><summary>Flag, naming and picture descriptions kept with this check</summary><p>Recorded index: ${c.input.index===null?'no flag':c.input.index}. Match response: ${esc(proposal(c.input.proposal))}. Numerator choice: ${esc(numerator(c.input.numerator))}.</p><p>Recorded reference description: ${esc(c.referencePictureText)}</p><p>Recorded working description: ${esc(c.workingPictureText)}</p><p>Support requested by this check: ${esc(c.input.support.join(', ')||'none recorded')}.</p><p class="tiny">These are recorded labels, descriptions and outcomes, not a new assessment.</p></details>${frozenSource(c.source)}</section>`;}
function keptPage(r){return `<h2 id="ribbon-match-prompt" tabindex="-1">Our kept ribbon trail</h2>${r.checks.length?checkRecord(r,r.checks.at(-1),r.checks.length-1):'<p>No check is kept yet. Making and naming remain open.</p>'}${button('data-ribbon-match-page="make"','Revise our working flag',true)} ${button('data-ribbon-match-page="name"','Revise our numerator')}${r.checks.length>1?`<details><summary>Earlier checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkRecord(r,c,i)).join('')}</details>`:''}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="ribbon-match-catalog"><h2>Choose a ribbon-label job</h2><p>Six ribbon jobs, each with a fixed reference. All are open. Starting makes a separate visit.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="ribbon-match-start-form"><label for="ribbon-match-case">Ribbon job</label><select id="ribbon-match-case" name="case">${ribbonMatchCases.map(s=>`<option value="${esc(s.id)}"${v.current?.source.id===s.id?' selected':''}>${esc(s.title)}</option>`).join('')}</select><button type="submit" class="secondary">Start this job</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our ribbon-match visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-ribbon-match-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable ribbon work (${v.earlier.length})</summary><p>The original work remains unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function ribbonMatchesPage(state){const v=matchView(state),r=v.current,header=`<header class="page-heading"><a class="back" href="#workshop"><span aria-hidden="true">←</span> Workshop</a> <a class="back" href="#cafe/fractions">Fraction Trail</a><h1>Same Amount, New Cuts</h1><p>Make a matching ribbon length with different equal parts, then name our actual flag.</p></header>`;if(v.status==='unavailable')return `<div class="ribbon-match-page">${header}<section class="ribbon-match-sheet"><h2>Earlier ribbon work is safe</h2><p>This saved format cannot be continued here. Fraction Trail and other tools remain open.</p><details><summary>Saved ribbon work</summary><pre>${esc(JSON.stringify(state.ribbonMatches,null,2))}</pre></details></section></div>`;return `<div class="ribbon-match-page">${header}<section class="ribbon-match-sheet">${r?`<nav class="ribbon-match-tabs" aria-label="Ribbon Matches pages">${ribbonMatchPages.map(p=>button(`data-ribbon-match-page="${p}" aria-current="${v.page===p?'page':'false'}"`,({make:'Make',name:'Name',kept:'Kept trail'})[p],v.page===p)).join('')}</nav><p class="ribbon-match-case-title"><strong>${esc(r.source.title)}</strong>${r.familiar?' · Job visited before':''}</p>`:''}<p id="ribbon-match-status" role="status" tabindex="-1"></p>${r?v.page==='name'?namePage(r):v.page==='kept'?keptPage(r):makePage(r):`<h2 id="ribbon-match-prompt" tabindex="-1">Two labels for one ribbon amount</h2><p>These are equal model wholes. Changing the cuts changes the parts, not the whole ribbon.</p>${catalog(v)}`}${r?`<details id="ribbon-match-label" data-round="${r.id}"><summary>Show our current fraction label</summary><p>Current working label: <strong>${esc(r.index===null?'No working flag yet':matchWorkingLabel(r.source,r.index))}</strong>.</p><p>This names the actual flag; it does not say whether that amount matches the reference.</p></details><details id="ribbon-match-help" data-round="${r.id}"><summary>Help us match and name</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear the ribbon explanation')}${button('data-ribbon-match-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}</details><details><summary>Choose another ribbon job</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function ribbonMatchesNotes(state){const v=matchView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Ribbon Matches · earlier format</summary><pre>${esc(JSON.stringify(state.ribbonMatches,null,2))}</pre></details>`;return `<details class="panel ribbon-match-page"><summary>Same Amount, New Cuts (${v.rounds.length} visits)</summary><p>Supplied-reference constructions with a required different partition, followed by naming the actual working flag. Reference labels and partitions are supplied. Fitting work does not establish independent drawing, fraction notation, explanation or a general equivalence algorithm. Matching and naming outcomes stay separate; optional descriptions, labels and feedback may supply clues.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Job visited before: ${r.familiar?'yes':'no'}. Current flag index: ${r.index===null?'absent':r.index}. Current match response: ${esc(proposal(r.proposal))}. Current numerator choice: ${esc(numerator(r.numerator))}. Current working label: ${esc(r.index===null?'No flag':matchWorkingLabel(r.source,r.index))}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${frozenSource(r.source)}${r.checks.map((c,i)=>checkRecord(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindRibbonMatches(state,{save,render,focus}){
 const boundId=matchView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&matchView(state).current?.id===boundId;
 const show=(message='',target='#ribbon-match-prompt')=>{const id=matchView(state).current?.id,open=[...document.querySelectorAll('.ribbon-match-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(matchView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#ribbon-match-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 const saveSupport=code=>{if(matchView(state).current?.support.includes(code))return;addMatchSupport(state,code);save();const r=matchView(state).current,h=document.querySelector('.ribbon-match-sheet .ribbon-match-record h3');if(h&&r?.checks.length){h.textContent=recordHeading(r,r.checks.at(-1),r.checks.length-1);const status=document.querySelector('#ribbon-match-status');if(status)status.textContent='Support request recorded. '+h.textContent+'.';}};
 document.querySelector('#ribbon-match-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||matchView(state).current?.id!==boundId)return;const r=startMatch(state,new FormData(form).get('case'));show(r?'A ribbon job is ready.':'A new visit cannot be created because its saved visit numbers have reached the supported limit.',r?'#ribbon-match-prompt':'#ribbon-match-status');});
 document.querySelectorAll('[data-ribbon-match-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||matchView(state).current?.id!==boundId)return;show(resumeMatch(state,Number(b.dataset.ribbonMatchResume))?'Earlier ribbon visit opened with its own source.':'That visit could not be opened.');}));
 bind('[data-ribbon-match-page]',b=>{setMatchPage(state,b.dataset.ribbonMatchPage);show();});
 bind('[data-ribbon-match-start-flag]',()=>{const ok=startMatchFlag(state);show(ok?'Working flag started at zero. The numerator choice is retained.':'No flag changed.','[data-ribbon-match-start-flag]');});
 bind('[data-ribbon-match-move]',b=>{const delta=Number(b.dataset.ribbonMatchMove),ok=moveMatchFlag(state,delta),r=matchView(state).current,next=r.index===null?null:r.index===0?1:r.index===r.source.workingDenominator?-1:delta;show(ok?'The flag moved one part and is our proposed match.':'The flag needs a position and room in that direction. No response changed.',next===null?'[data-ribbon-match-start-flag]':`[data-ribbon-match-move="${next}"]`);});
 bind('[data-ribbon-match-proposal]',b=>{const ok=chooseMatchProposal(state,b.dataset.ribbonMatchProposal);show(ok?b.dataset.ribbonMatchProposal==='flag'?'This flag is our proposed match.':'Not sure about the match selected; any existing flag is retained.':'A flag needs a position before it can be used.',ok?`[data-ribbon-match-proposal="${b.dataset.ribbonMatchProposal}"]`:'[data-ribbon-match-start-flag]');});
 bind('[data-ribbon-match-numerator]',b=>{chooseMatchNumerator(state,b.dataset.ribbonMatchNumerator==='unsure'?'unsure':Number(b.dataset.ribbonMatchNumerator));show('Naming choice changed. The flag and match response are unchanged.',`[data-ribbon-match-numerator="${b.dataset.ribbonMatchNumerator}"]`);});
 bind('[data-ribbon-match-clear-numerator]',()=>{chooseMatchNumerator(state,null);show('Naming left blank. The flag is retained.','[data-ribbon-match-clear-numerator]');});
 bind('[data-ribbon-match-check]',()=>{const c=checkMatch(state);if(c)setMatchPage(state,'kept');show(c?'Matching and naming responses are kept separately.':'This check could not be kept.',c?'.ribbon-match-record':'#ribbon-match-status');});
 bind('[data-ribbon-match-together]',()=>{addMatchSupport(state,'together');show('Let’s think it through together.','[data-ribbon-match-together]');});
 for(const [id,code]of [['ribbon-match-help','help'],['ribbon-match-label','label']]){const fold=document.getElementById(id);fold?.addEventListener('toggle',()=>{if(fold.open&&sameVisit(fold)&&Number(fold.dataset.round)===boundId)saveSupport(code);});}
 document.querySelectorAll('.ribbon-match-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))saveSupport('audio');}));
}
